glsl:
float sdf(vec3 pos) {
    float x = pos.x, y = pos.y, z = pos.z;
    float s = 3.0;
    float k = 0.3;
    float angle = k * z;
    float xw = x * cos(angle) - y * sin(angle);
    float yw = x * sin(angle) + y * cos(angle);
    float f = sin(s * xw) * cos(s * yw) + sin(s * yw) * cos(s * z) + sin(s * z) * cos(s * xw);
    float grad = s * 1.8;
    return abs(f) / grad - 0.08;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5*iResolution.xy) / iResolution.y;
    // Camera: drag horizontally to orbit, vertically to zoom; idle auto-spins.
    float t = iTime * 0.4 + 1.2;
    float cr = 3.0;
    if (iMouse.z > 0.0) {
        t = (iMouse.x / iResolution.x) * 6.2831853 + 1.2;
        cr = 3.0 * (0.45 + 1.4 * clamp(iMouse.y / iResolution.y, 0.0, 1.0));
    }
    vec3 ro = vec3(cr*cos(t), 0.8*3.0, cr*sin(t));
    vec3 ww = normalize(-ro);
    vec3 uu = normalize(cross(ww, vec3(0.0, 1.0, 0.0)));
    vec3 vv = cross(uu, ww);
    vec3 rd = normalize(uv.x*uu + uv.y*vv + 1.7*ww);

    float d = 0.001, max_d = 12.0;
    for (int i = 0; i < 96; i++) {
        float h = sdf(ro + d*rd);
        if (abs(h) < 0.0015*d || d > max_d) break;
        d += h * 0.75;
    }

    vec3 col = vec3(0.04, 0.02, 0.07);
    if (d < max_d) {
        vec3 p = ro + d*rd;
        float e = 0.001;
        vec3 n = normalize(vec3(
            sdf(p+vec3(e,0,0)) - sdf(p-vec3(e,0,0)),
            sdf(p+vec3(0,e,0)) - sdf(p-vec3(0,e,0)),
            sdf(p+vec3(0,0,e)) - sdf(p-vec3(0,0,e))
        ));
        vec3 ld = normalize(vec3(1.5, 2.0, -0.5));
        float diff = max(dot(n, ld), 0.0);
        float spec = pow(max(dot(reflect(-ld, n), -rd), 0.0), 48.0) * 0.7;
        col = vec3(0.15, 0.55, 0.85)*diff + spec + vec3(0.08, 0.04, 0.12)*(1.0-diff);
        col *= exp(-d * 0.12);
    }
    fragColor = vec4(pow(clamp(col, 0.0, 1.0), vec3(0.4545)), 1.0);
}
